class Control(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *a):
        pass

    def reply(self, obj, status=200):
        b = json.dumps(obj).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)

    def do_GET(self):
        if urlparse(self.path).path == "/journal":
            with J_LOCK:
                return self.reply(list(EVENTS))
        if urlparse(self.path).path == "/state":
            return self.reply(STATE)
        return self.reply({"error": "not found"}, 404)

    def do_POST(self):
        u = urlparse(self.path)
        q = parse_qs(u.query)
        if u.path == "/reset":
            with J_LOCK:
                EVENTS.clear()
            return self.reply({"ok": True})
        if u.path == "/mode":
            if "blackhole" in q:
                STATE["blackhole"] = q["blackhole"][0] == "1"
            if "stall" in q:
                want = q["stall"][0]
                if not re.fullmatch(r"\d{1,2}", want):
                    return self.reply({"error": "stall must be 0-99 seconds"}, 400)
                STATE["stall"] = int(want)
            return self.reply(STATE)
        if u.path == "/close":
            close_listener()
            return self.reply(STATE)
        if u.path == "/open":
            if LISTENER["sock"] is None:
                listen()
            return self.reply(STATE)
        return self.reply({"error": "not found"}, 404)


def main():
    global ARGS
    ap = argparse.ArgumentParser()
    ap.add_argument("--host", default="127.0.0.1")
    ap.add_argument("--port", type=int, default=1080)
    ap.add_argument("--user")
    ap.add_argument("--password")
    ap.add_argument("--journal")
    ap.add_argument("--blackhole", action="store_true",
                    help="accept SOCKS but refuse every CONNECT (negative test)")
    ap.add_argument("--map", action="append", default=[], metavar="NAME:PORT=IP:PORT",
                    help="fake-MagicDNS mapping, repeatable")
    ap.add_argument("--control-port", type=int, default=0)
    ARGS = ap.parse_args()
    ARGS.hostmap = {}
    for m in ARGS.map:
        src, dst = m.split("=")
        ip, pt = dst.rsplit(":", 1)
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)

    def do_GET(self):
        if self.path != "/__state":
            return self.reply({"error": "not found"}, 404)
        with STATE_LOCK:
            return self.reply({"reports": REPORTS, "requests": REQUESTS, "paths": list(PATHS),
                               "ws_open": len(WS_OPEN), "front": FRONT_STATUS,
                               "insets": INSETS, "root": ROOT_PROBE or "page",
                               "handshakes": HANDSHAKES})

    def do_POST(self):
        global FRONT_STATUS, ROOT_PROBE
        if self.path == "/__reset":
            with STATE_LOCK:
                REPORTS.clear()
                REQUESTS.clear()
